-- Region columns on members.
ALTER TABLE users ADD COLUMN city     TEXT NOT NULL DEFAULT '';
ALTER TABLE users ADD COLUMN state    TEXT NOT NULL DEFAULT '';
ALTER TABLE users ADD COLUMN zip      TEXT NOT NULL DEFAULT '';
ALTER TABLE users ADD COLUMN dma_slug TEXT NOT NULL DEFAULT '';
ALTER TABLE users ADD COLUMN dma_name TEXT NOT NULL DEFAULT '';

-- Region columns on companies.
ALTER TABLE companies ADD COLUMN city     TEXT NOT NULL DEFAULT '';
ALTER TABLE companies ADD COLUMN state    TEXT NOT NULL DEFAULT '';
ALTER TABLE companies ADD COLUMN zip      TEXT NOT NULL DEFAULT '';
ALTER TABLE companies ADD COLUMN dma_slug TEXT NOT NULL DEFAULT '';
ALTER TABLE companies ADD COLUMN dma_name TEXT NOT NULL DEFAULT '';

-- Region columns on events.
ALTER TABLE events ADD COLUMN city     TEXT NOT NULL DEFAULT '';
ALTER TABLE events ADD COLUMN state    TEXT NOT NULL DEFAULT '';
ALTER TABLE events ADD COLUMN zip      TEXT NOT NULL DEFAULT '';
ALTER TABLE events ADD COLUMN dma_slug TEXT NOT NULL DEFAULT '';
ALTER TABLE events ADD COLUMN dma_name TEXT NOT NULL DEFAULT '';

-- Optional region scope on board topics ('' = visible network-wide).
ALTER TABLE topics ADD COLUMN dma_slug TEXT NOT NULL DEFAULT '';
ALTER TABLE topics ADD COLUMN dma_name TEXT NOT NULL DEFAULT '';

